import { describe, it, expect } from 'vitest';
import { TestDataFactory } from './test-data-factory';
import { TagValueType, UpdateCycle } from '@/shared/enums/index';
import { TEST_USER_ID, TEST_CATEGORY_ID } from './constants';

describe('TestDataFactory', () => {
  describe('createTagPO', () => {
    it('should create a tag PO with default values', () => {
      const tagPO = TestDataFactory.createTagPO();

      // ID is now a UUID generated by generateTestUuid()
      expect(tagPO.id).toMatch(/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/);
      expect(tagPO.name).toBe('Test Tag');
      expect(tagPO.valueType).toBe(TagValueType.STRING);
      expect(tagPO.update_cycle).toBe(UpdateCycle.DAILY);
      expect(tagPO.ownedBy).toBe(TEST_USER_ID);
      expect(tagPO.isDeleted).toBe(false);
      expect(tagPO.categoryId).toBe(TEST_CATEGORY_ID);
    });

    it('should allow overriding default values', () => {
      const customId = 'custom-id';
      const tagPO = TestDataFactory.createTagPO({
        id: customId,
        name: 'Custom Tag',
        isDeleted: true,
      });

      expect(tagPO.id).toBe(customId);
      expect(tagPO.name).toBe('Custom Tag');
      expect(tagPO.isDeleted).toBe(true);
    });
  });

  describe('createTagVersionPO', () => {
    it('should create a tag version PO with default values', () => {
      const versionPO = TestDataFactory.createTagVersionPO();

      // ID is now a UUID generated by generateTestUuid()
      expect(versionPO.id).toMatch(/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/);
      expect(versionPO.tagId).toMatch(/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/);
      expect(versionPO.version).toBe(1);
      expect(versionPO.ownedBy).toBe(TEST_USER_ID);
    });
  });

  describe('createTagCategoryPO', () => {
    it('should create a tag category PO with default values', () => {
      const categoryPO = TestDataFactory.createTagCategoryPO();

      // ID is now TEST_CATEGORY_ID (UUID format)
      expect(categoryPO.id).toBe(TEST_CATEGORY_ID);
      expect(categoryPO.name).toBe('Test Category');
      expect(categoryPO.ownedBy).toBe(TEST_USER_ID);
    });
  });
});
